// Netlify build step: writes the demo and pre-built rooms into a JS module that
// gets bundled into the functions, so they never read files at runtime.
// Run with `npm run build` (Netlify runs it for you, see netlify.toml).

import fs from "node:fs/promises";
import path from "node:path";
import { readBuiltInRooms } from "../lib/roomStore.js";

const OUT = path.resolve("lib/generated/builtInRooms.js");

const rooms = await readBuiltInRooms();
await fs.mkdir(path.dirname(OUT), { recursive: true });
await fs.writeFile(
  OUT,
  `// Generated by scripts/bundle-rooms.js. Don't edit; rebuild instead.\nexport default ${JSON.stringify(rooms)};\n`,
);
console.log(`Bundled ${Object.keys(rooms).length} built-in rooms into ${path.relative(process.cwd(), OUT)}`);
